import { registerLoggingStream, unregisterLoggingStream } from '../../../server/bare/registry/logging-stream-registry.js';
export async function* handleLoggingStream(request) {
    const { id } = request;
    const logQueue = [];
    let pendingResolve = null;
    const streamHandler = (level, namespace, message, sourceId) => {
        const logResponse = {
            type: 'loggingStream',
            // For the global SDK_ALL_LOG_ID stream `sourceId` is the real origin of the
            // log; for a per-id stream it equals the subscription `id`.
            id: sourceId,
            level: level,
            namespace,
            message,
            timestamp: Date.now()
        };
        logQueue.push(logResponse);
        if (pendingResolve) {
            const resolve = pendingResolve;
            pendingResolve = null;
            resolve();
        }
    };
    registerLoggingStream(id, streamHandler);
    try {
        while (true) {
            while (logQueue.length > 0) {
                yield logQueue.shift();
            }
            // Wait for new logs - stream will terminate when client disconnects
            await new Promise((resolve) => {
                pendingResolve = resolve;
            });
        }
    }
    finally {
        unregisterLoggingStream(id, streamHandler);
    }
}
